<body>
<header>
  <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><h1>A18_2 · K線波段轉折觀察</h1><span class="tag">LIVE / HISTORY</span><nav class="workspace-tabs" aria-label="A18_2 操作模式"><button type="button" class="workspace-tab active" data-workspace-view="full">完整操作</button><button type="button" class="workspace-tab" data-workspace-view="simple">精簡下單</button><button type="button" class="workspace-tab" data-workspace-view="monitor">部位監控</button></nav><div id="dataModeControl" class="data-mode-control"><span id="dataModeBadge" class="data-mode-badge">資料模式：讀取中</span><button type="button" id="dataModeSwitch" disabled>讀取中…</button><span id="dataModeProgress" class="data-mode-progress"></span></div></div>
  <form id="controls" class="controls"><span class="section-no">1</span>
    <label>股票 <input id="symbol" value="2330" maxlength="12"></label>
    <button type="button" id="prevDay">← 上一日</button>
    <label>日期 <input id="date" type="date"> <strong id="weekday" style="color:var(--text)">—</strong></label>
    <button type="button" id="nextDay">下一日 →</button>
    <label>K線 <select id="interval"><option value="1">1秒</option><option value="5" selected>5秒</option><option value="15">15秒</option><option value="30">30秒</option><option value="60">1分</option><option value="180">3分</option><option value="300">5分</option><option value="600">10分</option><option value="900">15分</option><option value="1800">30分</option><option value="3600">60分</option></select></label>
    <label>微波段反轉 <select id="threshold"><option value="0.003">0.3%</option><option value="0.005">0.5%</option><option value="0.008">0.8%</option><option value="0.01" selected>1.0%</option><option value="0.015">1.5%</option><option value="0.02">2.0%</option></select></label>
    <label>主波段反轉 <select id="mainThreshold"><option value="0.01">1.0%</option><option value="0.015">1.5%</option><option value="0.02" selected>2.0%</option><option value="0.025">2.5%</option><option value="0.03">3.0%</option><option value="0.04">4.0%</option></select></label>
    <label>波段顯示 <select id="swingLayer"><option value="BOTH" selected>雙層</option><option value="MAIN">只看主波段</option><option value="MICRO">只看微波段</option><option value="NONE">不顯示</option></select></label>
    <label class="switch" title="以當日開盤為 0%，將加權指數 IX0001 疊加在主圖"><input id="overlay" type="checkbox"><span class="slider"></span><span>加權指數</span></label>
    <label class="switch" title="將目前日期之前的 N 個交易日一起接續畫在 K 線圖"><input id="multiDay" type="checkbox"><span class="slider"></span><span>多日</span></label>
    <label class="switch" title="隱藏所選交易日尚未揭露的 K 棒與所有圖上標記"><input id="lookaheadMask" type="checkbox"><span class="slider"></span><span>防偷看</span></label><span id="maskIndicator" class="mask-indicator" hidden>揭露至 —</span>
    <label id="lookbackWrap">往前 <input id="lookbackDays" type="number" min="1" max="20" value="1" style="width:58px"> 個交易日</label>
    <button type="submit">載入 / 更新</button>
    <label><input id="auto" type="checkbox" checked> 5秒自動更新</label>
    <label class="switch" title="顯示各功能區塊的數字編號"><input id="showSectionNumbers" type="checkbox" checked><span class="slider"></span><span>區塊編號</span></label>
    <label title="自動浮動：下捲隱藏、上捲一段距離才顯示；固定浮動：永遠固定最上方；僅頁首：完全不浮動">標題列 <select id="headerMode"><option value="AUTO">自動浮動</option><option value="PINNED">固定浮動</option><option value="STATIC">僅頁首</option></select></label>
  </form>
</header>
<main>
<div id="viewFull" class="workspace-view">
  <details id="foldGroupNav" class="top-fold top-fold-group" open>
    <summary><span class="section-no">2</span><span>群組導覽</span></summary>
    <section class="groupbar">
      <div class="group-row group-row-main"><button type="button" id="prevGroup">← 群</button><label>群組 <select id="groupSelect"><option value="">未選群組</option></select></label><button type="button" id="nextGroup">群 →</button></div>
      <div class="group-row"><button type="button" id="prevMember">← 股</button><label>群內個股 <select id="memberSelect"><option value="">—</option></select></label><button type="button" id="nextMember">股 →</button></div>
      <button type="button" id="manageGroups">管理群組</button>
