          <label class="manual-control-number">固定停損 % <input id="simStopPct" type="number" min="0" step="0.1" value="1"></label>
          <label class="manual-control-number">移動停利 % <input id="simTrailPct" type="number" min="0" step="0.1" value="1.5"></label>
          <label class="manual-control-number" title="浮盈達此百分比後，移動停利才永久啟動；0% 表示沿用原本有利水位即啟動">移動停利啟動 % <input id="simTrailActivationPct" type="number" min="0" max="50" step="0.1" value="0"></label>
