nReplaySizingMode"><option value="FLOOR">無條件捨去（原模式）</option><option value="CARRY_CEIL">累積差額進位</option></select></label></div><div class="campaign-section-title">每層部位 / 風控</div><table class="campaign-param-table"><thead><tr><th>Layer</th><th>資金%</th><th>風險%</th><th>停損%</th><th>啟動%</th><th>Trailing%</th></tr></thead><tbody><tr><td>Probe</td><td><input id="campaignProbeNotionalPct" type="number" step="0.1" value="40"></td><td><input id="campaignProbeRiskPct" type="number" step="0.1" value="50"></td><td><input id="campaignProbeStopPct" type="number" step="0.1" value="3"></td><td><input id="campaignProbeActivationPct" type="number" step="0.1" value="3.5"></td><td><input id="campaignProbeTrailPct" type="number" step="0.1" value="2.5"></td></tr><tr><td>Add1</td><td><input id="campaignAdd1NotionalPct" type="number" step="0.1" value="30"></td><td><input id="campaignAdd1RiskPct" type="number" step="0.1" value="30"></td><td><input id="campaignAdd1StopPct" type="number" step="0.1" value="2"></td><td><input id="campaignAdd1ActivationPct" type="number" step="0.1" value="2.5"></td><td><input id="campaignAdd1TrailPct" type="number" step="0.1" value="2"></td></tr><tr><td>Add2</td><td><input id="campaignAdd2NotionalPct" type="number" step="0.1" value="20"></td><td><input id="campaignAdd2RiskPct" type="number" step="0.1" value="12"></td><td><input id="campaignAdd2StopPct" type="number" step="0.1" value="1.5"></td><td><input id="campaignAdd2ActivationPct" type="number" step="0.1" value="2"></td><td><input id="campaignAdd2TrailPct" type="number" step="0.1" value="1.5"></td></tr><tr><td>Add3</td><td><input id="campaignAdd3NotionalPct" type="number" step="0.1" value="10"></td><td><input id="campaignAdd3RiskPct" type="number" step="0.1" value="8"></td><td><input id="campaignAdd3StopPct" type="number" step="0.1" value="1.5"></td><td><input id="campaignAdd3ActivationPct" type="number" step="0.1" value="2"></td><td><input id="campaignAdd3TrailPct" type="number" step="0.1" value="1.5"></td></tr></tbody></table><div class="campaign-section-title">加碼 / 失敗 / Reclaim 規則</div><div class="campaign-param-grid"><label>Add1 前進門檻 %<input id="campaignAdd1TriggerPct" type="number" step="0.1" value="1.5"></label><label>Layer cooldown 秒<input id="campaignCooldownSeconds" type="number" step="1" value="120"></label><label>Pullback 門檻 %<input id="campaignPullbackPct" type="number" step="0.1" value="0.5"></label><label>Re-break 超越 %<input id="campaignRebreakPct" type="number" step="0.1" value="0.2"></label><label>Momentum 延伸 %<input id="campaignMomentumPct" type="number" step="0.1" value="1.5"></label><label>Stalled 秒數<input id="campaignStallSeconds" type="number" step="1" value="300"></label><label>Stalled 最低延伸 %<input id="campaignStallMovePct" type="number" step="0.1" value="0.5"></label><label>Failed impulse 回落 %<input id="campaignFailurePullbackPct" type="number" step="0.1" value="1"></label><label>Reclaim 超越成本 %<input id="campaignReclaimPct" type="number" step="0.1" value="0.2"></label></div></div></details></div><div id="campaignReplayResult" class="sim-empty" style="margin-top:8px">先用「選擇進場」在 K 線標 Probe，再按「執行 Campaign 回放」。</div></div></details>
