<script>
(() => {
  async function copyChartPng() {
    const btn=document.getElementById('copyChartPng');
    const status=document.getElementById('copyChartPngStatus');
    const panel=document.querySelector('#viewFull .chart-panel');
    const base=document.getElementById('chart');
    if(!panel || !base || !base.width || !base.height){status.textContent='圖表尚未準備好';return;}
    btn.disabled=true;
    try {
      const rect=base.getBoundingClientRect();
      if(!rect.width || !rect.height)throw new Error('圖表尺寸無效');
      const scale=base.width/rect.width;
      const output=document.createElement('canvas');
      output.width=base.width;output.height=base.height;
      const ctx=output.getContext('2d');
      ctx.fillStyle=getComputedStyle(panel).backgroundColor || '#121c2a';
      ctx.fillRect(0,0,output.width,output.height);
      for(const id of ['chart','annotationChart','simChart','liveChart','maskChart','hoverChart']){
        const layer=document.getElementById(id);
        if(!layer || !layer.width || !layer.height || getComputedStyle(layer).display==='none')continue;
        const r=layer.getBoundingClientRect();
        ctx.drawImage(layer,(r.left-rect.left)*scale,(r.top-rect.top)*scale,r.width*scale,r.height*scale);
      }
      const blob=await new Promise(resolve=>output.toBlob(resolve,'image/png'));
      if(!blob)throw new Error('PNG 轉換失敗');
      if(navigator.clipboard?.write && window.ClipboardItem){
        try{
          await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);
          status.textContent='✓ 已複製 PNG 到剪貼簿';
          return;
        }catch(err){console.warn('PNG clipboard unavailable; falling back to download',err);}
      }
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');
      const symbol=document.getElementById('symbol')?.value?.trim() || 'chart';
      const date=document.getElementById('date')?.value || 'latest';
      a.href=url;a.download='A18_2_'+symbol+'_'+date+'.png';
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),1000);
      status.textContent='瀏覽器不支援圖片複製，已改下載 PNG';
    }catch(err){status.textContent='無法複製：'+(err?.message||String(err));}
    finally{btn.disabled=false;}
  }
  document.getElementById('copyChartPng')?.addEventListener('click',copyChartPng);
})();
</script>
