function syncSimpleRuntime(){const h=$('simpleRuntimeBadge'),c=$('simpleControlBadge');if(!h||!c)return;if(!state.runtimeReachable){h.textContent='A18_21 無法連線';h.className='simple-badge bad'}else{const real=state.runtimeHealth?.brokerProvider==='Yuanta'&&state.runtimeHealth?.enableBrokerExecution===true&&state.runtimeHealth?.enableRealOrders===true,account=state.runtimeHealth?.accountRefreshHealthy===true;h.textContent=account?`A18_21 ${state.runtimeHealth?.status||'OK'} · ${real?'REAL 已啟用':'REAL 未啟用'}`:`A18_21 ${state.runtimeHealth?.status||'DEGRADED'} · 帳務不可用`;h.className=`simple-badge ${account?(real?'ok':'warn'):'bad'}`}if(!state.runtimeControl){c.textContent='交易控制未知';c.className='simple-badge bad'}else if(state.runtimeControl.blocked){c.textContent='交易已封鎖';c.className='simple-badge bad'}else{c.textContent='交易控制未封鎖';c.className='simple-badge ok'}simpleEligibility()}
function syncExecutionMode(source){const v=$(source).value;$('executionMode').value=v;$('simpleExecutionMode').value=v;$('liveSend').textContent=v==='PAPER'?'建立 PAPER 虛擬單':'送出真單';$('simpleSend').textContent=v==='PAPER'?'建立 PAPER 虛擬單':'送出真單';liveEligibility();simpleEligibility();savePrefs()}
