function detectorWindow(bars,n,price){const w=bars.slice(-Math.min(n,bars.length));if(!w.length)return{ret:0,pos:50};const first=Number(w[0].open),hi=Math.max(...w.map(x=>Number(x.high))),lo=Math.min(...w.map(x=>Number(x.low)));return{ret:first?(price/first-1)*100:0,pos:hi>lo?(price-lo)/(hi-lo)*100:50}}
const detectorMinuteCache=new Map();async function detectorMinuteBars(day,symbol,{fresh=false}={}){const key=`${day}|${symbol}`;if(!fresh&&detectorMinuteCache.has(key))return detectorMinuteCache.get(key);const data=await liveJson(`/api/bars/${encodeURIComponent(symbol)}?date=${encodeURIComponent(day)}&interval=60`),bars=Array.isArray(data?.bars)?data.bars:[];detectorMinuteCache.set(key,bars);return bars}
function causalDetectorBars(bars,cutoff,seconds){const span=Math.max(1,+seconds||1)*1000;return (bars||[]).filter(b=>new Date(b.startTime).getTime()+span<=cutoff)}function classifyEntryDetector(bars,cutoff,direction){const xs=causalDetectorBars(bars,cutoff,60),n=xs.length;if(!n)return{regime:'WARMUP',advice:'OBSERVE',warmup:true,availableMinutes:0,price:0,return5m:0,return10m:0,return20m:0,position5m:50,position20m:50,volumeRatio5m:1,diagnostic:'固定 1 分 K · 開盤暖機：尚無完整 1 分 K；D2 若已有完整 5 秒 K 仍可獨立判斷 Timing。'};const price=Number(xs.at(-1).close),w5=detectorWindow(xs,5,price),w10=detectorWindow(xs,10,price),w20=detectorWindow(xs,20,price),vNow=xs.slice(-Math.min(5,n)).reduce((a,b)=>a+Number(b.volume||0),0),prevStart=Math.max(0,n-10),prevEnd=Math.max(0,n-5),prev=xs.slice(prevStart,prevEnd),vPrev=prev.reduce((a,b)=>a+Number(b.volume||0),0),vr=prev.length&&vPrev>0?(vNow/Math.min(5,n))/(vPrev/prev.length):1;let regime='BASE/MIXED',advice='OBSERVE';if(n<5){regime='OPENING_WARMUP'}else if(n<10){if(w5.ret>.45&&w5.pos>=80)regime='OPENING_MOMENTUM';else if(w5.ret<-.45&&w5.pos<=20)regime='OPENING_WEAKNESS';else regime='OPENING_MIXED';advice=regime==='OPENING_WEAKNESS'&&direction!=='SHORT'?'CAUTION':'OBSERVE'}else if(n<20){if(w5.ret>.45&&w10.ret>.6&&w5.pos>=80&&vr>=1.25){regime='EARLY_EXPANSION';advice='ALLOW'}else if(w5.ret<-.45&&w10.ret<-.6&&w5.pos<=20){regime='DOWNTREND';advice=direction==='SHORT'?'ALLOW':'BLOCK'}else if(w5.ret>.35&&w10.ret<0&&vr<1.1){regime='COUNTERTREND_BOUNCE';advice='INVERSE_CANDIDATE'}else regime='EARLY_MIXED'}else{if(w20.ret>2.5&&w20.pos>=85&&(vr<1||w10.ret<.5))regime='EXHAUSTION';else if(w5.ret>.35&&w10.ret<0&&w20.ret<0&&vr<1.1)regime='COUNTERTREND_BOUNCE';else if(w5.ret>.45&&w10.ret>.6&&w20.ret>.8&&w5.pos>=80&&w20.pos>=75&&vr>=1.25)regime='EXPANSION';else if(w5.ret>=.25&&w10.ret>=.5&&w20.ret>=.5&&w20.pos>=70&&vr>=1.5)regime='MOMENTUM_RESTART';else if(w20.ret>1.5&&w20.pos>=80&&w5.ret>0)regime='EXTENDED';else if(w5.ret<-.45&&w10.ret<-.6&&w5.pos<=20)regime='DOWNTREND';advice=regime==='EXPANSION'||regime==='MOMENTUM_RESTART'?'ALLOW':regime==='EXTENDED'?'REDUCE_SIZE':regime==='EXHAUSTION'?'BLOCK_ADD':regime==='COUNTERTREND_BOUNCE'?'INVERSE_CANDIDATE':regime==='DOWNTREND'?(direction==='SHORT'?'ALLOW':'BLOCK'):'OBSERVE'}const last=xs.at(-1)?.startTime||'',stage=n<5?`暖機 ${n}/5m`:n<10?`短窗 ${n}/10m`:n<20?`中窗 ${n}/20m`:'完整 20m+';return{regime,advice,warmup:n<20,availableMinutes:n,price,return5m:w5.ret,return10m:w10.ret,return20m:w20.ret,position5m:w5.pos,position20m:w20.pos,volumeRatio5m:vr,diagnostic:`固定 1 分 K · ${stage} · 截止 ${String(last).slice(11,19)} · ${regime} · ${advice} · 可用 ${n} 根 · 5m ${w5.ret>=0?'+':''}${w5.ret.toFixed(2)}% / 10m ${w10.ret>=0?'+':''}${w10.ret.toFixed(2)}% / 20m ${w20.ret>=0?'+':''}${w20.ret.toFixed(2)}% · 位置 ${w5.pos.toFixed(0)}%/${w20.pos.toFixed(0)}% · 量比 ${vr.toFixed(2)}x`}}
const detectorFiveSecondCache=new Map();async function detectorFiveSecondBars(day,symbol,{fresh=false}={}){const key=`${day}|${symbol}`;if(!fresh&&detectorFiveSecondCache.has(key))return detectorFiveSecondCache.get(key);const data=await liveJson(`/api/bars/${encodeURIComponent(symbol)}?date=${encodeURIComponent(day)}&interval=5`),bars=Array.isArray(data?.bars)?data.bars:[];detectorFiveSecondCache.set(key,bars);return bars}
function classifyEntryTimingV2(bars,cutoff,direction){const xs=causalDetectorBars(bars,cutoff,5).slice(-12);if(xs.length<6)return{timing:'WARMUP',timingAdvice:'OBSERVE',timingDiagnostic:`5秒 Timing 資料不足：${xs.length} 根`};const last6=xs.slice(-6),last3=xs.slice(-3),p0=Number(last6[0].open),p=Number(last6.at(-1).close),ret30=p0?(p/p0-1)*100:0,ret15=Number(last3[0].open)?(p/Number(last3[0].open)-1)*100:0,steps=last3.map(x=>Math.sign(Number(x.close)-Number(x.open))),up3=steps.filter(x=>x>0).length,down3=steps.filter(x=>x<0).length,hi=Math.max(...last6.map(x=>Number(x.high))),lo=Math.min(...last6.map(x=>Number(x.low))),pos=hi>lo?(p-lo)/(hi-lo)*100:50,long=direction!=='SHORT';let timing='STALL';if((long&&down3>=2&&ret15<0)||(!long&&up3>=2&&ret15>0))timing='PULLBACK';else if((long&&up3>=2&&ret15>0&&pos>=70)||(!long&&down3>=2&&ret15<0&&pos<=30))timing='PUSH';else{const prev=xs.slice(-12,-6),prevMove=prev.length&&Number(prev[0].open)?(Number(prev.at(-1).close)/Number(prev[0].open)-1)*100:0;if((long&&ret30>0&&prevMove<=0)||(!long&&ret30<0&&prevMove>=0))timing='REACCELERATION'}const timingAdvice=timing==='PUSH'||timing==='REACCELERATION'?'CONFIRM':timing==='PULLBACK'?'WAIT':'NEUTRAL';return{timing,timingAdvice,return15s:ret15,return30s:ret30,position30s:pos,timingDiagnostic:`5秒 Timing · ${timing} · ${timingAdvice} · 15s ${ret15>=0?'+':''}${ret15.toFixed(2)}% / 30s ${ret30>=0?'+':''}${ret30.toFixed(2)}% · 30s位置 ${pos.toFixed(0)}% · 最近3根 ↑${up3}/↓${down3}`}}
async function runEntryDetector(atTime=null,direction=null,{fresh=false}={}){const day=atTime?String(atTime).slice(0,10):$('date').value,symbol=state.symbol||$('symbol').value.trim(),cutoff=atTime?new Date(atTime).getTime():Date.now(),minuteBars=await detectorMinuteBars(day,symbol,{fresh}),base=classifyEntryDetector(minuteBars,cutoff,direction),version=$('probeDetectorVersion')?.value==='D2'?'D2':'D1';if(version==='D1')return{...base,version};const fiveBars=await detectorFiveSecondBars(day,symbol,{fresh});return{...base,...classifyEntryTimingV2(fiveBars,cutoff,direction),version}}

function detectorExplanation(x,direction){const long=direction!=='SHORT',up=x.return5m>0&&x.return10m>0&&x.return20m>0,high=x.position20m>=80,low=x.position20m<=20,vol=x.volumeRatio5m;const map={EXPANSION:{title:'趨勢正在擴張',action:'可考慮順勢進場；若已持有，也屬於相對合理的加碼區。',risk:'重點是確認這是趨勢展開，而不是已經漲太久。'},MOMENTUM_RESTART:{title:'動能重新啟動',action:'前一段整理後又出現推進力，可以考慮順勢，但品質通常略低於早期 EXPANSION。',risk:'留意重新啟動是否只有短暫放量，後續若無延續就不要追價。'},EXTENDED:{title:'趨勢仍在，但位置已經延伸',action:'不代表一定會跌，但新進場或大幅加碼的風險報酬開始變差；較適合縮小部位。',risk:'最大的風險是買在趨勢後段，價格只要失去延續就容易出現較深回撤。'},EXHAUSTION:{title:'高檔動能正在衰竭',action:'不建議再 ADD；若已持有，應把注意力轉向保護既有獲利。',risk:'價格可能仍在高位，但短期推進速度或量能已經跟不上，容易從追價變成接最後一棒。'},COUNTERTREND_BOUNCE:{title:'目前比較像逆勢反彈',action:long?'做多要特別保守；短線雖然反彈，但中段結構仍偏弱。':'若原本想做空，這可能只是下降趨勢中的反彈，可等待反彈失敗確認。',risk:'只看最近幾分鐘容易誤認成新趨勢，10～20 分鐘方向尚未真正翻轉。'},DOWNTREND:{title:'短中期結構偏空',action:long?'目前不利追多，建議等待止跌或結構翻轉。':'方向與空方趨勢一致，可以觀察是否有延續。',risk:'若逆勢操作，停損被觸發的機率通常較高。'},'BASE/MIXED':{title:'訊號混合，沒有明確優勢',action:'目前不足以單靠 Regime 支持進場或加碼，建議搭配結構、量價或原本交易理由。',risk:'不同時間尺度沒有形成一致方向，容易來回震盪。'},WARMUP:{title:'資料還不足',action:'先不要依賴探測器判斷。',risk:'開盤初期樣本太少，5/10/20 分鐘特徵尚未完整。'}};const degraded={OPENING_WARMUP:{title:'開盤暖機中',action:'已用目前形成的完整 1 分 K 退化計算；先以觀察為主，D2 可獨立提供 5 秒 Timing。',risk:'樣本尚未滿 5 分鐘，短線雜訊很高。'},OPENING_MOMENTUM:{title:'開盤短線動能偏強',action:'5 分鐘窗已可用，但 10/20 分鐘尚未形成；先視為早盤動能，不等同完整 EXPANSION。',risk:'開盤波動大，短窗容易快速反轉。'},OPENING_WEAKNESS:{title:'開盤短線偏弱',action:'短窗結構偏弱；做多先保守，等待更多分鐘資料確認。',risk:'尚無 10/20 分鐘背景，不能當成完整空頭 Regime。'},OPENING_MIXED:{title:'開盤短窗訊號混合',action:'已有 5 分鐘資訊但方向不一致，繼續觀察。',risk:'10/20 分鐘背景尚未形成。'},EARLY_EXPANSION:{title:'早盤擴張候選',action:'5/10 分鐘已同向且量價支持，可作為早期順勢參考；20 分鐘形成後再升級完整判斷。',risk:'目前仍缺完整 20 分鐘背景。'},EARLY_MIXED:{title:'早盤中窗訊號混合',action:'5/10 分鐘已可判斷，但尚無足夠證據支持完整 Regime。',risk:'20 分鐘背景尚未形成。'}};const m=degraded[x.regime]||map[x.regime]||map['BASE/MIXED'];let why=[];if(x.warmup)why.push(`開盤退化模式：目前 ${x.availableMinutes} 根完整 1 分 K；未滿的長週期使用現有資料，不等待、不阻塞。`);why.push(`5/10/20 分鐘報酬 ${x.return5m>=0?'+':''}${x.return5m.toFixed(2)}% / ${x.return10m>=0?'+':''}${x.return10m.toFixed(2)}% / ${x.return20m>=0?'+':''}${x.return20m.toFixed(2)}%${up?'，三個尺度同向偏強':''}`);why.push(`目前位於近 5/20 分鐘區間的 ${x.position5m.toFixed(0)}% / ${x.position20m.toFixed(0)}%${high?'，位置偏高':low?'，位置偏低':''}`);why.push(`最近 5 分鐘量能約為前 5 分鐘的 ${vol.toFixed(2)} 倍${vol>=1.5?'，量能明顯放大':vol<1?'，量能正在收縮':'，量能沒有極端變化'}`);return{...m,why}}
async function renderProbeDetector(){const el=$('probeDetectorResult');if(!el)return;if(!$('probeDetectorEnabled').checked){el.textContent='探測器關閉。';el.className='detector-result';return}if(!state.simEntryTime){el.textContent='請先用「選擇進場」指定 Probe。';el.className='detector-result warn';return}el.textContent='固定 1 分 K 計算中…';const direction=$('simDirection').value,x=await runEntryDetector(state.simEntryTime,direction),m=detectorExplanation(x,direction),symbol=state.symbol||$('symbol').value.trim(),name=symbolNames[symbol]||'',cut=String(state.simEntryTime).slice(11,19);el.innerHTML=`<div class="detector-human"><div class="detector-human-head"><strong>${esc(symbol)} ${esc(name)}</strong><span>${esc(cut)} · ${esc(direction)}</span></div><div class="detector-human-title">${esc(m.title)}</div><div class="detector-human-action"><b>怎麼看：</b>${esc(m.action)}</div><div class="detector-human-risk"><b>主要風險：</b>${esc(m.risk)}</div><div class="detector-human-why"><b>判斷依據</b>${m.why.map(v=>`<div>• ${esc(v)}</div>`).join('')}</div>${x.version==='D2'?`<div class="detector-human-why"><b>5 秒 Entry Timing</b><div>• ${esc(x.timing)} / ${esc(x.timingAdvice)}</div><div>• 15 秒 ${x.return15s>=0?'+':''}${x.return15s.toFixed(2)}%，30 秒 ${x.return30s>=0?'+':''}${x.return30s.toFixed(2)}%，30 秒位置 ${x.position30s.toFixed(0)}%</div></div>`:''}<details class="detector-raw"><summary>查看原始 Regime / 數值</summary><div>${esc(x.diagnostic)}${x.version==='D2'?`<br>${esc(x.timingDiagnostic)}`:''}</div></details></div>`;el.className=`detector-result ${['ALLOW'].includes(x.advice)?'allow':['BLOCK','BLOCK_ADD','INVERSE_CANDIDATE'].includes(x.advice)?'block':'warn'}`}
let liveDetectorBusy=false;async function renderLiveDetector(){const el=$('probeDetectorResult');if(!el||!$('liveDetectorEnabled')?.checked||liveDetectorBusy)return;const symbol=state.symbol||$('symbol').value.trim();if(!symbol)return;liveDetectorBusy=true;try{const direction=$('simDirection').value;el.textContent='盤中即時探測中…';el.className='detector-result';const x=await runEntryDetector(null,direction,{fresh:true}),m=detectorExplanation(x,direction),name=symbolNames[symbol]||'',now=new Date(),cut=now.toLocaleTimeString('zh-TW',{hour12:false});el.innerHTML=`<div class="detector-human"><div class="detector-human-head"><strong>${esc(symbol)} ${esc(name)}</strong><span>LIVE ${esc(cut)} · 假設 ${esc(direction)} 進場</span></div><div class="detector-human-title">${esc(m.title)}</div><div class="detector-human-action"><b>怎麼看：</b>${esc(m.action)}</div><div class="detector-human-risk"><b>主要風險：</b>${esc(m.risk)}</div><div class="detector-human-why"><b>判斷依據</b>${m.why.map(v=>`<div>• ${esc(v)}</div>`).join('')}</div>${x.version==='D2'?`<div class="detector-human-why"><b>5 秒 Entry Timing</b><div>• ${esc(x.timing)} / ${esc(x.timingAdvice)}</div><div>• 15 秒 ${x.return15s>=0?'+':''}${x.return15s.toFixed(2)}%，30 秒 ${x.return30s>=0?'+':''}${x.return30s.toFixed(2)}%，30 秒位置 ${x.position30s.toFixed(0)}%</div></div>`:''}<details class="detector-raw"><summary>查看原始 Regime / 數值</summary><div>${esc(x.diagnostic)}${x.version==='D2'?`<br>${esc(x.timingDiagnostic)}`:''}</div></details></div>`;el.className=`detector-result ${['ALLOW'].includes(x.advice)?'allow':['BLOCK','BLOCK_ADD','INVERSE_CANDIDATE'].includes(x.advice)?'block':'warn'}`}catch(e){el.textContent=`盤中探測失敗：${e?.message||e}`;el.className='detector-result warn'}finally{liveDetectorBusy=false}}
function syncLiveDetector(){if($('liveDetectorEnabled')?.checked)renderLiveDetector();else renderProbeDetector()}
async function preOrderDetectorConfirm(direction){const x=await runEntryDetector(null,direction,{fresh:true});const risky=['BLOCK','BLOCK_ADD','INVERSE_CANDIDATE'].includes(x.advice),msg=`下單前探測結果\n\nRegime：${x.regime}\n建議：${x.advice}\n${x.diagnostic}\n\n這只是 Shadow 第二意見，不會自動替你否決交易。\n是否仍要進入真單確認？`;return confirm(msg)}
async function sendSimpleLiveOrder(){if(!simpleEligibility())return;const p=createSimpleLivePayload(),paper=$('simpleExecutionMode').value==='PAPER';if($('simplePreOrderDetectorEnabled')?.checked&&!(await preOrderDetectorConfirm(p.direction)))return;if(!confirm(`${paper?'PAPER 虛擬單':'REAL 真單'}\n\n股票：${p.symbolOrName} ${symbolNames[p.symbolOrName]||''}\n方向：${p.direction}\n股數：${p.quantityShares}\n\n${paper?'不會送至元大；會由 A18_21 虛擬部位接管。':'警告：這會送出 REAL 真實委託。'}\n是否繼續？`))return;$('simpleSend').disabled=true;try{if(paper){const ref=liveReferenceBar();await liveJson('/api/runtime21/paper/entries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:p,referencePrice:ref?Number(ref.close):null})});await loadPaperAccount();}else{const row=await liveJson('/api/runtime21/entries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});state.activeEntryId=row.id;sessionStorage.setItem(liveSessionKey,row.id);state.liveEntry=row;state.liveEntries=[row,...state.liveEntries.filter(x=>String(x.id).toLowerCase()!==String(row.id).toLowerCase())]}await pollRuntime21()}catch(e){$('simpleEligibility').textContent=`建立${paper?'PAPER':'REAL'}計畫失敗：${e.message}`;$('simpleEligibility').className='simple-status blocked'}finally{simpleEligibility()}}
function monitorFmt(v){return v==null?'—':Number(v).toLocaleString('zh-TW',{maximumFractionDigits:4})}
let monitorRowsCache=[],overnightPromptDismissedKey='';
