let paperAccountCache=null,paperHistoryRangeExplicit=false;function paperFillDate(x){return String(x?.occurredAt||'').slice(0,10)}function renderPaperAccount(data){paperAccountCache=data;const positions=Array.isArray(data?.positions)?data.positions:[],fills=Array.isArray(data?.fills)?data.fills:[],active=positions.filter(x=>['active','paused'].includes(String(x.status||'').toLowerCase())&&Number(x.managedQuantity||0)>0),realized=Number(data?.realizedPnl||0),unrealized=Number(data?.unrealizedPnl||0);$('paperAccountSummary').textContent=`${active.length} active · 浮動 ${fmtMoney(unrealized)} · 已實現 ${fmtMoney(realized)}`;if($('simplePaperSummary'))$('simplePaperSummary').textContent=`PAPER 帳戶：${active.length} active｜浮動 ${fmtMoney(unrealized)}｜已實現 ${fmtMoney(realized)}｜${fills.length} fills；詳細請看「部位監控」。`;$('paperAccountKpis').innerHTML=`<div><small>Active</small><strong>${active.length}</strong></div><div><small>未實現 P/L</small><strong class="${unrealized>=0?'monitor-pos':'monitor-neg'}">${fmtMoney(unrealized)}</strong></div><div><small>已實現 P/L</small><strong class="${realized>=0?'monitor-pos':'monitor-neg'}">${fmtMoney(realized)}</strong></div><div><small>Fills</small><strong>${fills.length}</strong></div>`;$('paperPositionRows').innerHTML=positions.slice().sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))).map(x=>`<tr><td><strong>${esc(x.status)}</strong></td><td>${esc(x.symbol)} ${esc(x.name||'')}</td><td>${esc(x.direction)}</td><td>${Number(x.managedQuantity||0).toLocaleString('zh-TW')}</td><td>${fmtP(x.averagePrice)}</td><td>${x.updatedAt?new Date(x.updatedAt).toLocaleString('zh-TW'):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">尚無 PAPER 部位。</td></tr>';const sortedFills=fills.slice().sort((a,b)=>String(b.occurredAt||'').localeCompare(String(a.occurredAt||''))),latest=sortedFills.map(paperFillDate).filter(Boolean).sort().at(-1)||'',ps=$('paperHistoryStart')?.value||'',pe=$('paperHistoryEnd')?.value||'',visibleFills=paperHistoryRa