async function pollRuntime21(){if(state.livePollBusy)return;state.livePollBusy=true;try{const [health,control,entries,orders,decisions]=await Promise.allSettled([liveJson('/api/runtime21/health'),liveJson('/api/runtime21/trading-control'),liveJson('/api/runtime21/entries'),liveJson('/api/runtime21/orders'),liveJson('/api/runtime21/decisions?limit=1000')]);state.runtimeHealth=health.status==='fulfilled'?health.value:null;state.runtimeControl=control.status==='fulfilled'?control.value:null;state.runtimeReachable=health.status==='fulfilled'&&control.status==='fulfilled';state.liveHistoryReachable=entries.status==='fulfilled'&&Array.isArray(entries.value);if(state.liveHistoryReachable)state.liveEntries=entries.value;if(orders.status==='fulfilled'&&Array.isArray(orders.value))state.liveOrders=orders.value;if(decisions.status==='fulfilled'&&Array.isArray(decisions.value))state.liveAllDecisions=decisions.value.sort((a,b)=>new Date(b.occurredAt)-new Date(a.occurredAt));setRuntimeBadges();renderRealCampaignList();if(state.activeEntryId){const p=state.liveEntries.find(x=>String(x.id).toLowerCase()===String(state.activeEntryId).toLowerCase());if(p){state.liveEntry=p;state.liveDecisions=p.takeoverId?state.liveAllDecisions.filter(d=>String(d.takeoverId).toLowerCase()===String(p.takeoverId).toLowerCase()):[];if(p.takeoverId){try{state.liveTakeover=await liveJson(`/api/runtime21/takeovers/${encodeURIComponent(p.takeoverId)}`)}catch{state.liveTakeover=null}}else state.liveTakeover=null}else if(state.liveHistoryReachable){state.activeEntryId=null;state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[];sessionStorage.removeItem(liveSessionKey)}}else{state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[]}renderLive()}finally{state.livePollBusy=false}}
function liveReferenceBar(){const day=$('date').value,rows=revealedBars().filter(b=>String(b.startTime).slice(0,10)===day);return rows.length?rows[rows.length-1]:null}
