function addCosts(result,direction,p){const {entryPrice,exitPrice}=result,amount=price=>price*p.quantity,fee=value=>Math.max(Math.trunc(p.minFee),Math.trunc(value*p.feeRate)),taxMode=p.holdingMode==='SWING'?'NORMAL':p.taxMode,taxRate=taxMode==='DAYTRADE'?.0015:.003,entryAmount=amount(entryPrice),exitAmount=amount(exitPrice),entryFee=fee(entryAmount),exitFee=fee(exitAmount),tax=Math.trunc((direction==='LONG'?exitAmount:entryAmount)*taxRate),gross=Math.trunc((direction==='LONG'?exitPrice-entryPrice:entryPrice-exitPrice)*p.quantity),net=direction==='LONG'?(exitAmount-exitFee-tax)-(entryAmount+entryFee):(entryAmount-entryFee-tax)-(exitAmount+exitFee),basis=direction==='LONG'?entryAmount+entryFee:entryAmount-entryFee-tax;return{...result,gross,entryFee,exitFee,tax,net:Math.trunc(net),actualReturn:net/Math.abs(basis||entryAmount)*100}}
