function campaignStageZh(x){return({PROBE:'Probe 探索',FOLLOW_THROUGH:'Follow-through 趨勢延續',STALLED:'Stalled 動能停滯',DEFENSIVE:'Defensive 防守',RECLAIM:'Reclaim 重新確認',CLOSED:'Closed 已結算'})[x]||x}
