const markerLabelLayout={boxes:[]};
function resetMarkerLabelLayout(){markerLabelLayout.boxes.length=0}
function markerLabelVariant(full,compact,minimal){const span=Number(state.chartView?.end??1)-Number(state.chartView?.start??0);return span<=.28?full:span<=.62?compact:minimal}
