  c.save();c.font=font;const w=Math.ceil(c.measureText(text).width),h=13,lanes=5,base=above?g.p.t+15:g.h-g.p.b-8,step=15;
  let chosen=null;
  for(let lane=0;lane<lanes;lane++){
    const baseline=above?base+lane*step:base-lane*step,l=Math.max(g.p.l+2,Math.min(g.w-g.p.r-w-2,x+7)),box={l,r:l+w,t:baseline-h,b:baseline+3};
    if(!markerLabelLayout.boxes.some(b=>markerBoxesOverlap(box,b))){chosen={baseline,box,l};break}
  }
  if(!chosen){const baseline=above?base+(lanes-1)*step:base-(lanes-1)*step,l=Math.max(g.p.l+2,Math.min(g.w-g.p.r-w-2,x+7));chosen={baseline,box:{l,r:l+w,t:baseline-h,b:baseline+3},l}}
  markerLabelLayout.boxes.push(chosen.box);
  const targetX=Math.max(chosen.box.l,Math.min(chosen.box.r,x)),targetY=above?chosen.box.b:chosen.box.t;
  if(Math.abs(targetY-anchorY)>18){c.strokeStyle=color;c.globalAlpha=.38;c.lineWidth=1;c.setLineDash([2,3]);c.beginPath();c.moveTo(x,anchorY+(above?-8:8));c.lineTo(targetX,targetY);c.stroke();c.setLineDash([]);c.globalAlpha=1}
