function zigzag(bars,th){if(!bars.length)return{turns:[],candidate:null};const pts=bars.map(b=>({time:b.startTime,price:Number(b.close)}));let dir=0,ext=pts[0],hi=pts[0],lo=pts[0];const turns=[];for(let i=1;i<pts.length;i++){const p=pts[i];if(dir===0){if(p.price>=hi.price)hi=p;if(p.price<=lo.price)lo=p;if((hi.price-p.price)/hi.price>=th){turns.push({...hi,type:'H'});dir=-1;ext=p}else if((p.price-lo.price)/lo.price>=th){turns.push({...lo,type:'L'});dir=1;ext=p}}else if(dir===1){if(p.price>=ext.price)ext=p;else if((ext.price-p.price)/ext.price>=th){turns.push({...ext,type:'H'});dir=-1;ext=p}}else{if(p.price<=ext.price)ext=p;else if((p.price-ext.price)/ext.price>=th){turns.push({...ext,type:'L'});dir=1;ext=p}}}let h=0,l=0;return{turns:turns.map(x=>({...x,label:x.type==='H'?`H${++h}`:`L${++l}`})),candidate:dir===0?null:{...ext,type:dir===1?'H':'L'}}}
