function createTimeGeometry(bars,w,h,p,y){
  const plotW=Math.max(1,w-p.l-p.r),intervalSec=Math.max(1,+$('interval').value||1),view=state.chartView,viewStart=Math.max(0,Math.min(.9999,Number(view.start)||0)),viewEnd=Math.max(viewStart+.0001,Math.min(1,Number(view.end)||1)),viewSpan=viewEnd-viewStart;
  const days=[...new Set(bars.map(b=>String(b.startTime).slice(0,10)))],dayIndex=new Map(days.map((d,i)=>[d,i])),sessionSeconds=4.5*60*60,fullDays=Math.max(1,days.length),dayW=plotW/(fullDays*viewSpan);
  const dayStart=d=>new Date(`${d}T09:00:00+08:00`).getTime(),dayEnd=d=>new Date(`${d}T13:30:00+08:00`).getTime();
  const globalAtTime=time=>{const d=String(time||'').slice(0,10),di=dayIndex.get(d);if(di==null)return 0;const t=new Date(time).getTime(),start=dayStart(d),end=dayEnd(d),ratio=Math.max(0,Math.min(1,(t-start)/Math.max(1,end-start)));return(di+ratio)/fullDays};
