  const xAtIndex=i=>i>=0&&i<bars.length?xAtTime(bars[i].startTime):p.l;
  const xs=bars.map((_,i)=>xAtIndex(i));
  const nearestIndex=x=>{if(!xs.length)return-1;let lo=0,hi=xs.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(xs[mid]<x)lo=mid+1;else hi=mid}const a=lo,b=Math.max(0,lo-1);return Math.abs(xs[a]-x)<Math.abs(xs[b]-x)?a:b};
  const timeAtX=x=>{const clamped=Math.max(p.l,Math.min(w-p.r,x)),local=(clamped-p.l)/plotW,global=Math.max(0,Math.min(.999999,viewStart+local*viewSpan)),scaled=global*fullDays,di=Math.max(0,Math.min(days.length-1,Math.floor(scaled))),d=days[di],ratio=Math.max(0,Math.min(1,scaled-di));return dayStart(d)+ratio*(dayEnd(d)-dayStart(d))};
  const dayLeft=k=>xAtGlobal(k/fullDays),dayRight=k=>xAtGlobal((k+1)/fullDays),isXVisible=x=>x>=p.l-2&&x<=w-p.r+2;
