  const bars=state.bars,w=r.width,h=r.height,p={l:64,r:18,t:20,b:32};c.clearRect(0,0,w,h);if(!bars.length){c.fillStyle='#8191a8';c.fillText('此日期尚無 K 線資料',p.l,p.t+15);return}
  const lo=Math.min(...bars.map(b=>Number(b.low))),hi=Math.max(...bars.map(b=>Number(b.high))),rg=hi-lo||Math.max(1,hi*.001),min=lo-rg*.08,max=hi+rg*.08,y=v=>p.t+(max-v)/(max-min)*(h-p.t-p.b);
