// On a closed-market day, default to the latest trading date (unless a date was explicitly requested in the URL).
if(!qd&&$('date').value===today){
  try{
    const closed=await fetch(`/api/calendar/non-trading/${today}`,{cache:'no-store'}).then(r=>r.json());
    if(closed.nonTrading){
      let d=new Date(today+'T12:00:00');
      for(let i=0;i<15;i++){
        d.setDate(d.getDate()-1);
        if(d.getDay()===0||d.getDay()===6)continue;
        const day=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
        const response=await fetch(`/api/calendar/non-trading/${day}`,{cache:'no-store'});
        if(response.ok&&(await response.json()).nonTrading)continue;
        $('date').value=day;break;
      }
    }
  }catch(e){console.warn('Could not resolve latest trading date',e)}
}
// STAGING_CLOSED_DATE_FALLBACK: persisted closed-market dates should not produce an empty testing page.
if(location.hostname.startsWith('staging-')&&!qd){
  try{
    let current=$('date').value;
    for(let attempt=0;attempt<20;attempt++){
      const res=await fetch(`/api/calendar/non-trading/${current}`,{cache:'no-store'});
      if(!res.ok||!(await res.json()).nonTrading)break;
      const d=new Date(current+'T12:00:00');d.setDate(d.getDate()-1);
      current=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      $('date').value=current;
    }
  }catch(e){console.warn('Staging trading-date fallback failed',e)}
}
updateWeekday();syncBlock4TargetControls();await loadGroups();if(prefs.group&&groupNames().includes(prefs.group)){$('groupSelect').value=prefs.group;renderMembers()}wireWorkspace();syncSimpleFromCanonical();setWorkspaceView(location.hash==='#simple'?'simple':location.hash==='#monitor'?'monitor':'full',{hash:false});state.timer=setInterval(load,5000);setInterval(pollRuntime21,2000);setInterval(pollOperationModeControl,1500);setInterval(()=>{if($('liveDetectorEnabled')?.checked)renderLiveDetector()},5000);setInterval(loadPaperAccount,2000);setInterval(()=>loadPositionMonitor({render:false,forcePrompt:true}),2000);pollRuntime21();pollOperationModeControl();loadPaperAccount();loadPositionMonitor({render:workspaceView==='monitor',forcePrompt:true});if(typeof prefs.simEntryTime==='string'&&prefs.simEntrySymbol===$('symbol').value.trim().toUpperCase()&&prefs.simEntryTime.slice(0,10)===$('date').value)state.simEntryTime=prefs.simEntryTime;load()}const threeGreenOverlayState={key:'',signals:[],busy:false};
function scanThreeGreenBars(bars,mode=$('threeGreenMode').value,version=$('threeGreenVersion').value,limitSeconds=Number($('threeGreenLimit').value)){
  const signals=[];let previousClose=null,previousDay='',upTimes=[];
  for(const b of [...bars].sort((a,b)=>Date.parse(a.startTime)-Date.parse(b.startTime))){
    const close=Number(b.close),day=String(b.startTime).slice(0,10);
    if(!Number.isFinite(close))continue;
    if(previousDay&&day!==previousDay){previousClose=null;upTimes=[]}
    previousDay=day;
    if(previousClose!==null){
      if(close>previousClose){
        upTimes.push(b.startTime);
        if(version==='V2'){
          // Count the entire third 5-second candle as elapsed time, inclusive of the limit.
          const completedAt=Date.parse(b.startTime)+5000;
          while(upTimes.length&&completedAt-Date.parse(upTimes[0])>limitSeconds*1000)upTimes.shift();
        }
        if(upTimes.length===3){
          signals.push({time:new Date(Date.parse(b.startTime)+5000).toISOString(),barTime:b.startTime,price:close,start:upTimes[0]});
          upTimes=mode==='SLIDING'?upTimes.slice(-2):[];
        }
      }else if(close<previousClose){upTimes=[]}
      // Equal close: do not add, do not reset.
    }
    previousClose=close;
  }
  return signals;
}
async function loadThreeGreenOverlay(force=false){
  const toggle=$('threeGreenOverlay');
  if(!toggle?.checked){draw();return}
  const sym=$('symbol').value.trim().toUpperCase(),day=$('date').value,key=sym+'|'+day+'|'+$('threeGreenMode').value+'|'+$('threeGreenVersion').value+'|'+$('threeGreenLimit').value+'|'+$('multiDay').checked;
  if(!force&&threeGreenOverlayState.key===key){draw();return}
  if(threeGreenOverlayState.busy)return;
  threeGreenOverlayState.busy=true;
  try{
    const days=$('multiDay').checked&&state.loadedDates.length?state.loadedDates:[day];
    const responses=await Promise.all(days.map(d=>fetchBars(sym,d,5)));
    const signals=responses.flatMap((response,i)=>scanThreeGreenBars(response.bars||[]));
    if(sym!==$('symbol').value.trim().toUpperCase()||day!==$('date').value)return;
    threeGreenOverlayState.signals=signals;threeGreenOverlayState.key=key;
  }catch(e){$('threeGreenResult').textContent='K 線標記載入失敗：'+e.message}
  finally{threeGreenOverlayState.busy=false;draw()}
}
// Staging-only research signal: three truly adjacent completed 5-second bullish bars.
if(location.hostname.startsWith('staging-') || location.hostname==='127.0.0.1' || location.hostname==='localhost'){
  const panel=$('threeGreenPanel');panel.style.display='block';
  $('threeGreenOverlay').addEventListener('change',()=>{savePrefs();loadThreeGreenOverlay(true)});
  $('threeGreenMode').addEventListener('change',()=>{threeGreenOverlayState.key='';savePrefs();loadThreeGreenOverlay(true);$('threeGreenScan').click()});
  for(const id of ['threeGreenVersion','threeGreenLimit'])$(id).addEventListener('change',()=>{ $('threeGreenLimitWrap').style.display=$('threeGreenVersion').value==='V2'?'':'none';threeGreenOverlayState.key='';savePrefs();loadThreeGreenOverlay(true);$('threeGreenScan').click()});
  const scan=$('threeGreenScan');
  scan.addEventListener('click',async()=>{
    const sym=$('symbol').value.trim().toUpperCase(),day=$('date').value;
    const out=$('threeGreenResult'),list=$('threeGreenList');
    out.textContent='正在掃描完整 5 秒 K…';list.replaceChildren();scan.disabled=true;
    try{
      const response=await fetchBars(sym,day,5);
      const bars=(response.bars||[]).filter(b=>b&&Number.isFinite(Date.parse(b.startTime))).sort((a,b)=>Date.parse(a.startTime)-Date.parse(b.startTime));
      const matches=scanThreeGreenBars(bars).map(x=>({
        time:new Date(x.time).toLocaleTimeString('zh-TW',{hour12:false,timeZone:'Asia/Taipei'}),
        close:x.price,start:x.start
      }));
      out.textContent=sym+'／'+day+'：5 秒 K 共 '+bars.length+' 根，符合累積三次收盤價上升的訊號 '+matches.length+' 次（'+($('threeGreenVersion').value==='V2'?'V2 '+$('threeGreenLimit').value+'秒':'V1 不限時')+'／'+($('threeGreenMode').value==='SLIDING'?'B 滑動':'A 不重疊')+'）。來源：'+(response.source||'—');
      if(!matches.length)return;
      const table=document.createElement('table');table.style.width='100%';
      const head=document.createElement('thead');head.innerHTML='<tr><th>觸發時間</th><th>第 3 根收盤價</th><th>首根時間</th></tr>';table.append(head);
      const body=document.createElement('tbody');
      for(const m of matches.slice(0,250)){
        const tr=document.createElement('tr');
        for(const value of [m.time,String(m.close),String(m.start).slice(11,19)]){
          const td=document.createElement('td');td.textContent=value;tr.append(td);
        }
        body.append(tr);
      }
      table.append(body);list.append(table);
      if(matches.length>250){const note=document.createElement('p');note.textContent='僅顯示前 250 次；總數如上。';list.append(note)}
    }catch(err){out.textContent='掃描失敗：'+err.message}
    finally{scan.disabled=false}
  });
}

